"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[14547],{27562:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SchwarmfeuerController","desc":"Renders every placed Schwarmfeuer for all players and runs the local gunner\'s\\nlocking. Per turret (`Discovery`): a `TurretRig` eased to the replicated aim,\\nthe 12 pod doors swung by their `Hinge` joints toward `PodsOpen` over\\n`DoorOpenTime` (`Hinge` attribute `OpenAngle`), and the missile tips hidden as\\nthe `Ammo` attribute falls (tube k shows while k > MagazineSize - Ammo).\\n\\nGunner (`Gunner` hooks): while the trigger is held with full pods, every\\nenemy that stays inside `LockConeDeg` of the crosshair, in range and in sight\\nfor `LockTime` gets a lock (max 12, one per enemy) and a spinning amber\\ndiamond (`GuiAssets.SchwarmfeuerLock`, only on this client). Releasing the\\ntrigger sends `ReqSchwarmfeuerFire` with the locks; the server decides.\\n\\nMissiles: each `SchwarmfeuerLaunched` flies a copy of that tube\'s missile with\\na smoke trail, stepped with the server\'s `SchwarmfeuerMath.stepMissile`, until\\nits `ExplosionAt`, its target\'s fuse radius or `MaxFlightTime`.","realm":["Client"],"source":{"line":22,"path":"src/StarterPlayer/StarterPlayerScripts/SchwarmfeuerController.client.luau"}}')}}]);